  "Каждый отрезок — отдельная генерация H3 длиной <b>17k+5</b> кадров (24 fps). Отрезок в режиме <b>«Продление»</b> начинается с хвоста предыдущего: кадры перекрытия фиксируются в латенте и подаются как ключевой клип, а последний кадр предыдущего отрезка добавляется ещё одним <b>&lt;Picture N&gt;</b>. Так персонажи и свет не «плывут» между отрезками.": "แต่ละช่วงคือการสร้าง H3 แยกกันยาว <b>17k+5</b> เฟรม (24 fps) ช่วงในโหมด <b>“ต่อเนื่อง”</b> จะเริ่มจากท้ายของช่วงก่อนหน้า: เฟรมที่ซ้อนทับถูกล็อกใน latent และป้อนเป็นคลิปหลัก ส่วนเฟรมสุดท้ายของช่วงก่อนหน้าจะถูกเพิ่มเป็น <b>&lt;Picture N&gt;</b> อีกหนึ่งภาพ วิธีนี้ช่วยไม่ให้ตัวละครและแสงเพี้ยนระหว่างช่วง",
  "<b>«Новая сцена»</b> — монтажная склейка: отрезок генерируется с нуля, без связи с предыдущим.": "<b>“ฉากใหม่”</b> คือการตัดแบบฉับพลัน: ช่วงถูกสร้างใหม่ตั้งแต่ต้น ไม่เชื่อมกับช่วงก่อนหน้า",
  "Готовые отрезки кэшируются в <b>output/h3zerostudio/": "ช่วงที่เสร็จแล้วถูกแคชไว้ใน <b>output/h3zerostudio/",
  "</b>. Повторный запуск пропускает неизменённые отрезки; изменение отрезка пересчитывает его и все продолжения после него.": "</b> การรันซ้ำจะข้ามช่วงที่ไม่เปลี่ยน การแก้ไขช่วงจะคำนวณช่วงนั้นและทุกช่วงต่อเนื่องหลังจากนั้นใหม่",
  "Обучающий диапазон H3 — {0}–{1} кадров ({2}–{3} с) на отрезок. Сейчас в проекте: {4} кадров, {5} с.": "ช่วงที่ H3 ฝึกมา: {0}–{1} เฟรม ({2}–{3} วิ) ต่อช่วง ขณะนี้โปรเจกต์: {4} เฟรม, {5} วิ",
  "<span>Очистить кэш проекта</span>": "<span>ล้างแคชโปรเจกต์</span>",
  "Готовые дубли остаются (восстановятся без генерации)": "เทคที่เสร็จแล้วยังอยู่ (กู้คืนได้โดยไม่ต้องสร้าง)",
  "Кэш и все готовые дубли (кроме зафиксированных)": "แคชและเทคที่เสร็จแล้วทั้งหมด (ยกเว้นที่ล็อกไว้)",
