  "В архив попадут проект, все его ассеты (картинки, аудио, видео) и папка генераций: дубли, финалы, зафиксированные отрезки.": "ไฟล์เก็บถาวรประกอบด้วยโปรเจกต์ แอสเซ็ตทั้งหมด (ภาพ เสียง วิดีโอ) และโฟลเดอร์ผลการสร้าง: เทค ฉบับจริง ช่วงที่ล็อก",
