  "Кто есть кто": "ใครเป็นใคร",
  "Каждая метка с новой строки: <Picture N>, <Video N>, <Audio N> (или своя <Subject N>) — что это (персонаж, предмет, локация, стиль, движение, голос) и что именно берётся из референса: внешность, одежда, детали, роль в ролике.": "แต่ละป้ายขึ้นบรรทัดใหม่: <Picture N>, <Video N>, <Audio N> (หรือ <Subject N> ของคุณเอง) — คืออะไร (ตัวละคร วัตถุ สถานที่ สไตล์ การเคลื่อนไหว เสียงพูด) และนำอะไรจากอ้างอิงมาใช้: ลุค เสื้อผ้า รายละเอียด บทบาทในวิดีโอ",
  "Кратко": "สรุป",
  "Один абзац. Начинается с типа задачи в квадратных скобках: [reference generation], [keyframe completion], [video editing], [video continuation], [audio reuse], [audio reference] (можно сочетать через +). Что за ролик, главные герои, как используются референсы.": "หนึ่งย่อหน้า ขึ้นต้นด้วยประเภทงานในวงเล็บเหลี่ยม: [reference generation], [keyframe completion], [video editing], [video continuation], [audio reuse], [audio reference] (รวมกันได้ด้วย +) วิดีโอเกี่ยวกับอะไร ตัวละครหลัก และใช้อ้างอิงอย่างไร",
  "Для каждой метки — насколько точно её сохранить: fully_preserved (почти без изменений), partially_preserved (часть черт меняется), attribute_transfer (черты переносятся на другой объект), weak_reference (только стиль/атмосфера). Для аудио: fully_copy, partially_copy, reference, weak_reference.": "สำหรับแต่ละป้าย — ต้องรักษาไว้อย่างไร: fully_preserved (แทบไม่เปลี่ยน), partially_preserved (ลักษณะบางอย่างเปลี่ยน), attribute_transfer (ลักษณะย้ายไปยังวัตถุอื่น), weak_reference (เฉพาะสไตล์/อารมณ์) สำหรับเสียง: fully_copy, partially_copy, reference, weak_reference",
  "Основное описание": "คำอธิบายหลัก",
  "Главная часть промпта. 1–2 предложения про стиль, реализм, свет, палитру и атмосферу, затем кадры по порядку: [Shot 1], [Shot 2] At 00:03.500 … В каждом: композиция, персонаж (по референсам), действие, камера (ракурс, объектив, движение), свет, звук. Реплики: <Subject 1> (S1) says: <d>[Russian] текст</d>. Обычно 350–500 слов.": "ส่วนหลักของพรอมต์ 1–2 ประโยคเกี่ยวกับสไตล์ ความสมจริง แสง จานสี และบรรยากาศ ตามด้วยช็อตตามลำดับ: [Shot 1], [Shot 2] At 00:03.500 … แต่ละช็อตมี: องค์ประกอบภาพ ตัวละคร (ตามอ้างอิง) แอ็กชัน กล้อง (มุม เลนส์ การเคลื่อนไหว) แสง เสียง บทพูด: <Subject 1> (S1) says: <d>[English] text</d> ปกติ 350–500 คำ",
  "Звуковая среда": "ซาวด์สเคป",
  "Фон и физические звуки сцены: эмбиент, шаги, ветер, ткань, предметы. Без диалогов.": "เสียงพื้นหลังและเสียงทางกายภาพของฉาก: บรรยากาศ เสียงเท้า ลม ผ้า วัตถุ ไม่มีบทสนทนา",
