  "Рекомендуемый формат (Full-Reference): разделы по порядку, ключ с двоеточием в начале строки, текст — по-английски.": "รูปแบบที่แนะนำ (Full-Reference): ส่วนต่างๆ ตามลำดับ คีย์ตามด้วยโคลอนที่ต้นบรรทัด ข้อความเป็นภาษาอังกฤษ",
