  "⚠ Разделы не по порядку — H3 обучен на порядке сверху вниз. ": "⚠ ส่วนต่างๆ ไม่เรียงลำดับ — H3 ฝึกด้วยลำดับจากบนลงล่าง ",
  "⚠ Повтор: {0}": "⚠ ซ้ำ: {0}",
  "Метки": "ป้าย",
  "<Picture N>, <Video N>, <Audio N> — номера идут в порядке референсов (картинки: персонажи → локации → другое). <Subject N> — своя метка персонажа/объекта: опишите её в subject_definitions. Наберите @, чтобы выбрать референс из списка.": "<Picture N>, <Video N>, <Audio N> — หมายเลขเรียงตามลำดับอ้างอิง (ภาพ: ตัวละคร → สถานที่ → อื่นๆ) <Subject N> — ป้ายตัวละคร/วัตถุของคุณเอง: อธิบายใน subject_definitions พิมพ์ @ เพื่อเลือกอ้างอิงจากรายการ",
  "Шаблон вставлен, прежний текст перенесён в detailed_description (Ctrl+Z — отменить)": "แทรกเทมเพลตแล้ว ข้อความเดิมย้ายไปที่ detailed_description (Ctrl+Z — เลิกทำ)",
