  "Текст изменён. Закрыть без сохранения?": "ข้อความถูกเปลี่ยน ปิดโดยไม่บันทึกหรือไม่?",
  "Не сохранять": "ไม่บันทึก",
  "Вернуться (Esc)": "ย้อนกลับ (Esc)",
  "✂ Участок: тяните по видеодорожке — внутри сцены, через склейку / промежуток (мост), в промежутке до сцены (пролог) или за её конец · Esc — выход": "✂ สแปน: ลากไปตามแทร็กวิดีโอ — ภายในฉาก ข้ามคัต / ช่องว่าง (สะพาน) ในช่องว่างก่อนฉาก (บทนำ) หรือเลยท้ายฉาก · Esc — ออก",
  "<b>✂</b><span>Участок</span>": "<b>✂</b><span>สแปน</span>",
  "Пересоздать участок (R): включите и тяните по таймлайну — выделенная часть ролика перегенерируется,\nа видео и звук до и после неё остаются и служат контекстом.\nВыделение может пересекать склейку или промежуток (мост), начинаться в промежутке до сцены (пролог)\nили заходить за её конец (продолжение). Повторное нажатие или Esc — выход": "สร้างสแปนใหม่ (R): เปิดแล้วลากไปตามไทม์ไลน์ — ส่วนที่เลือกของวิดีโอจะถูกสร้างใหม่\nขณะที่วิดีโอและเสียงก่อนและหลังยังอยู่และใช้เป็นบริบท\nการเลือกข้ามคัตหรือช่องว่างได้ (สะพาน) เริ่มในช่องว่างก่อนฉากได้ (บทนำ)\nหรือเลยท้ายฉากได้ (ต่อเนื่อง) กดอีกครั้งหรือ Esc — ออก",
  "тяните по видеодорожке — можно через склейку или промежуток · Esc — выход": "ลากไปตามแทร็กวิดีโอ — ข้ามคัตหรือช่องว่างได้ · Esc — ออก",
