  "Дубль устарел: изменились клипы или настройки под участком — в ролике сейчас пусто/старое. ↻ Пересоздать — в карточке участка или в меню (правый клик)": "เทคล้าสมัย: คลิปหรือการตั้งค่าใต้สแปนเปลี่ยน — วิดีโอตอนนี้แสดงเฟรมว่าง/เก่า ↻ สร้างใหม่ — ในการ์ดสแปนหรือเมนู (คลิกขวา)",
