  "Удалить {0} общих файлов ({1} МБ) из input/h3zerostudio и _thumbs?\nНи один сохранённый проект на них не ссылается.": "ลบไฟล์ที่ใช้ร่วมกัน {0} ไฟล์ ({1} MB) จาก input/h3zerostudio และ _thumbs หรือไม่?\nไม่มีโปรเจกต์ที่บันทึกไว้อ้างถึงไฟล์เหล่านี้",
  "\nПроекты, которые есть только внутри workflow (не в списке «Проекты»), не учитываются — откройте их сначала.\n\n": "\nโปรเจกต์ที่มีอยู่แค่ในเวิร์กโฟลว์ (ไม่อยู่ในรายการ “โปรเจกต์”) จะไม่ถูกนับ — เปิดโปรเจกต์เหล่านั้นก่อน\n\n",
  "Удалено файлов: {0} ({1} МБ)": "ลบไฟล์แล้ว: {0} ({1} MB)",
  "Применены глобальные настройки ({0} парам.) — {1} клип(ов) устарели. «Только этот проект» в «Настройках» — оставить проекту свои": "ใช้การตั้งค่ารวมแล้ว ({0} พารามิเตอร์) — {1} คลิปล้าสมัย “เฉพาะโปรเจกต์นี้” ใน “ตั้งค่า” จะเก็บค่าของโปรเจกต์ไว้",
  "Не удалось сохранить глобальные настройки: ": "บันทึกการตั้งค่ารวมไม่ได้: ",
  "Проект хранит свои настройки: их изменения не затрагивают другие проекты": "โปรเจกต์ใช้การตั้งค่าของตัวเอง: การเปลี่ยนจะไม่กระทบโปรเจกต์อื่น",
  "Настройки этого проекта стали глобальными": "การตั้งค่าของโปรเจกต์นี้กลายเป็นการตั้งค่ารวมแล้ว",
  "Проект следует глобальным настройкам: изменено {0} парам. (часть клипов может устареть; Ctrl+Z — вернуть)": "โปรเจกต์ใช้การตั้งค่ารวม: เปลี่ยน {0} พารามิเตอร์ (บางคลิปอาจล้าสมัย; Ctrl+Z — เลิกทำ)",
  "Проект следует глобальным настройкам": "โปรเจกต์ใช้การตั้งค่ารวม",
  "Сделать настройки этого проекта глобальными? Проекты с «Для всех проектов» получат их при открытии.": "ตั้งการตั้งค่าของโปรเจกต์นี้เป็นการตั้งค่ารวมหรือไม่? โปรเจกต์ที่ตั้งเป็น “สำหรับทุกโปรเจกต์” จะได้รับเมื่อเปิด",
  "Глобальные настройки = настройки этого проекта": "การตั้งค่ารวม = การตั้งค่าของโปรเจกต์นี้",
