  "✦ Чистовик только этого клипа: черновик (если нет) → апскейл → доработка σ {0} до {1}×{2}, {3} («Настройки» → «Этап 2»)": "✦ ฉบับจริงเฉพาะคลิปนี้: ร่าง (ถ้ายังไม่มี) → อัปสเกล → รีไฟน์ σ {0} เป็น {1}×{2}, {3} (“ตั้งค่า” → “ขั้นที่ 2”)",
