  "0 — видео заморожено (картинка остаётся такой же); больше нуля разрешает частично менять видео": "0 — วิดีโอถูกตรึง (ภาพคงเดิม); มากกว่าศูนย์จะอนุญาตให้วิดีโอเปลี่ยนบางส่วน",
  "Сэмплер, cfg, расписание, промпт и референсы — как у отрезка. Нужен вход audio_vae. Исходный клип не затирается: звук сохраняется отдельной копией.": "Sampler, cfg, scheduler พรอมต์ และอ้างอิง — ตามช่วง ต้องใช้อินพุต audio_vae คลิปต้นฉบับไม่ถูกเขียนทับ: เสียงถูกบันทึกเป็นสำเนาแยก",
  "Улучшить": "ปรับปรุง",
  "✎ Черновик этого клипа": "✎ ร่างของคลิปนี้",
  "✦ Чистовик этого клипа": "✦ ฉบับจริงของคลิปนี้",
  "♪ Улучшить звук": "♪ ปรับปรุงเสียง",
  "Дополнительные шаги семплера только по звуку клипа; картинка не меняется": "สเต็ป sampler เพิ่มเติมเฉพาะเสียงของคลิป ภาพไม่เปลี่ยน",
