  "Только этот проект": "เฉพาะโปรเจกต์นี้",
  "Свои настройки проекта: изменения не затрагивают другие проекты": "การตั้งค่าของโปรเจกต์เอง: การเปลี่ยนไม่กระทบโปรเจกต์อื่น",
  "Изменения здесь сохраняются глобально и применяются ко всем проектам с «Для всех проектов».": "การเปลี่ยนที่นี่จะบันทึกแบบรวมและมีผลกับทุกโปรเจกต์ที่ตั้งเป็น “สำหรับทุกโปรเจกต์”",
  "Этот проект хранит свои настройки (так открываются проекты прошлых версий, чтобы их клипы не устарели).": "โปรเจกต์นี้ใช้การตั้งค่าของตัวเอง (โปรเจกต์จากเวอร์ชันเก่าเปิดแบบนี้เพื่อไม่ให้คลิปล้าสมัย)",
  "Записать настройки этого проекта как глобальные": "บันทึกการตั้งค่าของโปรเจกต์นี้เป็นการตั้งค่ารวม",
