  "«Сгенерировать»: черновик {0}×{1} → сразу чистовик {2}×{3} по каждому отрезку": "“สร้าง”: ร่าง {0}×{1} → ฉบับจริง {2}×{3} ทันทีสำหรับแต่ละช่วง",
  "2 этапа: каждый отрезок сначала черновиком {0}×{1}, затем сразу чистовик — апскейл и доработка до {2}×{3} (композиция, движение и звук черновика сохраняются).": "2 ขั้นตอน: แต่ละช่วงเป็นร่าง {0}×{1} ก่อน แล้วไปเป็นฉบับจริงทันที — อัปสเกลและรีไฟน์เป็น {2}×{3} (คงองค์ประกอบภาพ การเคลื่อนไหว และเสียงของร่างไว้)",
  "1 этап: каждый отрезок сразу в {0}×{1}.": "1 ขั้นตอน: แต่ละช่วงสร้างที่ {0}×{1} ทันที",
