  "единственный этап": "ขั้นตอนเดียว",
  "Turbo LoRA Ref2VA: 4 шага, cfg 1. Без LoRA — ~20 шагов. shift видео 0 — расписание модели. fps — всегда 24 (H3).": "Turbo LoRA Ref2VA: 4 สเต็ป, cfg 1 หากไม่มี LoRA — ประมาณ 20 สเต็ป Video shift 0 — ตารางของโมเดล fps เป็น 24 เสมอ (H3)",
