  "Размер плитки. Больше — меньше плиток и быстрее, но больше VRAM; меньше — больше деталей на плитку, дольше. Кратно 32.": "ขนาดไทล์ ใหญ่ขึ้น — ไทล์น้อยลงและเร็วขึ้น แต่ใช้ VRAM มากขึ้น; เล็กลง — รายละเอียดต่อไทล์มากขึ้น ช้าลง ทวีคูณของ 32",
