  "Апскейл отрезка": "อัปสเกลช่วง",
  "Только этот клип (результат — новый дубль, звук 1:1)": "เฉพาะคลิปนี้ (ผลลัพธ์เป็นเทคใหม่ เสียง 1:1)",
  "<b>↑</b><span>Апскейл отрезка</span>": "<b>↑</b><span>อัปสเกลช่วง</span>",
  "Метод и размер — Настройки → «Апскейл». Весь ролик — кнопка «↑ Апскейл» в шапке.": "วิธีและขนาด — ตั้งค่า → “อัปสเกล” ทั้งวิดีโอ — ปุ่ม “↑ อัปสเกล” ที่ส่วนหัว",
  "Сначала сгенерируйте участок (↻ Пересоздать): апскейл делается из его дубля": "สร้างสแปนก่อน (↻ สร้างใหม่): อัปสเกลจะทำจากเทคของสแปน",
  "Участок {0}: апскейл {1} уже есть": "สแปน {0}: มีอัปสเกล {1} อยู่แล้ว",
