  "Апскейл участка": "อัปสเกลสแปน",
  "Апскейл дубля участка (его окно + доработка, звук 1:1); правый клик по участку — другой метод / размер": "อัปสเกลเทคของสแปน (หน้าต่างของสแปน + รีไฟน์ เสียง 1:1); คลิกขวาที่สแปน — วิธี / ขนาดอื่น",
  "<b>↑</b><span>Апскейл</span>": "<b>↑</b><span>อัปสเกล</span>",
  "↑ Апскейл всего ролика: {0} отр. · {1} → {2} ({3})\nКаждый отрезок увеличивается своим окном и дорабатывается коротким проходом H3, звук 1:1; готовые берутся из кэша.\nПравый клик — другой метод или размер": "↑ อัปสเกลทั้งวิดีโอ: {0} ช่วง · {1} → {2} ({3})\nแต่ละช่วงถูกอัปสเกลในหน้าต่างของตัวเองและรีไฟน์ด้วยรอบ H3 สั้นๆ เสียง 1:1 ที่เสร็จแล้วมาจากแคช\nคลิกขวา — วิธีหรือขนาดอื่น",
  "↑ Апскейл всего ролика": "↑ อัปสเกลทั้งวิดีโอ",
  "Обученный латентный апскейлер H3 (быстро, без декода/энкода) → доработка": "latent อัปสเกลเลอร์ที่ฝึกมาของ H3 (เร็ว ไม่ต้องถอด/เข้ารหัส) → รีไฟน์",
  "Апскейл → синхронные плитки (SyncTile): каждая плитка видит промпт и референсы отрезка": "อัปสเกล → ไทล์แบบซิงก์ (SyncTile): แต่ละไทล์เห็นพรอมต์และอ้างอิงของช่วง",
  " · вход: {0} · у метода свои настройки": " · อินพุต: {0} · วิธีนี้มีการตั้งค่าของตัวเอง",
  "Размер кадра после апскейла в мегапикселях. Пропорции — как у проекта, стороны кратны 32": "ขนาดเฟรมหลังอัปสเกลเป็นเมกะพิกเซล สัดส่วนตามโปรเจกต์ ด้านเป็นทวีคูณของ 32",
  " (не больше кадра)": " (ไม่ใหญ่กว่าเฟรม)",
