  "свой размер, Мп…": "ขนาดกำหนดเอง, MP…",
  "Кадр проекта {0}×{1} ({2} Мп) → ": "เฟรมโปรเจกต์ {0}×{1} ({2} MP) → ",
  " ({0} Мп, ×{1})": " ({0} MP, ×{1})",
  "Длинный клип увеличивается по кускам: каждый кусок — свой апскейл и доработка, затем VRAM освобождается. Меньше кусок — меньше VRAM, но больше перекрытий (дольше). Длина прилипает к сетке H3 (17k+5 кадров)": "คลิปยาวจะถูกอัปสเกลเป็นชิ้น: แต่ละชิ้นอัปสเกลและรีไฟน์แยกกัน แล้วคืน VRAM ชิ้นเล็กลง — ใช้ VRAM น้อยลง แต่ซ้อนทับมากขึ้น (ช้าลง) ความยาวจับกริด H3 (17k+5 เฟรม)",
  "≈{0} с → {1} кадр. ({2} с)": "≈{0} วิ → {1} เฟรม ({2} วิ)",
  " · по умолчанию": " · ค่าเริ่มต้น",
  "Перекрытие соседних кусков: следующий кусок продолжает чистый хвост предыдущего (как продление), стык смешивается при декодировании": "ส่วนซ้อนทับของชิ้นข้างเคียง: ชิ้นถัดไปต่อจากท้ายที่สะอาดของชิ้นก่อนหน้า (เหมือนการต่อเนื่อง) รอยต่อจะถูกผสมตอนถอดรหัส",
  "{0} с → {1}": "{0} วิ → {1}",
  "По кускам ({0})": "เป็นชิ้น ({0})",
