  " Плитки работают внутри каждого куска.": " ไทล์ทำงานภายในแต่ละชิ้น",
  "Клип целиком за один проход — нужно больше VRAM.": "ทั้งคลิปในรอบเดียว — ใช้ VRAM มากกว่า",
  "Сила доработки (σ старта): меньше — бережнее, больше — больше новых деталей": "ความแรงของรีไฟน์ (σ เริ่มต้น): ต่ำ — นุ่มนวลกว่า, สูง — รายละเอียดใหม่มากขึ้น",
  "Шаги доработки после апскейла (для этого метода)": "สเต็ปรีไฟน์หลังอัปสเกล (สำหรับวิธีนี้)",
  "{0} шаг.": "{0} สเต็ป",
