  "Ниже — настройки метода «{0}». У каждого метода свои: переключение их не сбрасывает.": "ด้านล่างคือการตั้งค่าของวิธี “{0}” แต่ละวิธีมีการตั้งค่าของตัวเอง: การสลับไม่รีเซ็ตค่า",
