  "Расписание": "Scheduler",
  "Плитки": "ไทล์",
  "«↑ Апскейл» в шапке — весь ролик (каждый отрезок своим окном, длинные — по кускам, звук 1:1, готовые из кэша). ↑ на клипе или в его меню — только этот клип. Результат — новый дубль, старый можно вернуть.": "“↑ อัปสเกล” ที่ส่วนหัว — ทั้งวิดีโอ (แต่ละช่วงในหน้าต่างของตัวเอง ช่วงยาวเป็นชิ้น เสียง 1:1 ที่เสร็จแล้วมาจากแคช) ↑ บนคลิปหรือในเมนูของคลิป — เฉพาะคลิปนี้ ผลลัพธ์เป็นเทคใหม่ เทคเก่าคืนค่าได้",
  "Видео загружено: {0} · перетащите на дорожку (футаж) или на отрезок (референс <Video>)": "โหลดวิดีโอแล้ว: {0} · ลากไปที่แทร็ก (ฟุตเทจ) หรือไปที่ช่วง (อ้างอิง <Video>)",
  "{0} · зафикс.": "{0} · ล็อก",
  "Убрать из проекта (файл остаётся)": "นำออกจากโปรเจกต์ (ไฟล์ยังอยู่)",
  " · со звуком": " · มีเสียง",
  "{0}\n{1}{2}{3}\nПеретащите на пустую часть видеодорожки — футаж (продолжить / перегенерировать часть).\nНа отрезок или клик — референс <Video> выбранного отрезка.": "{0}\n{1}{2}{3}\nลากไปที่ส่วนว่างของแทร็กวิดีโอ — ฟุตเทจ (ต่อ / สร้างบางส่วนใหม่)\nไปที่ช่วงหรือคลิก — อ้างอิง <Video> ของช่วงที่เลือก",
  "🔒 Фикс": "🔒 ล็อก",
  "Этот файл лежит на таймлайне как футаж. Убрать ассет и превратить эти клипы в обычные отрезки?": "ไฟล์นี้อยู่บนไทม์ไลน์เป็นฟุตเทจ นำแอสเซ็ตออกและเปลี่ยนคลิปเหล่านี้เป็นช่วงปกติหรือไม่?",
  ", из {0} с": ", จาก {0} วิ",
  "Футаж «{0}» на таймлайне ({1} с{2}). Следующий отрезок продолжит его": "ฟุตเทจ “{0}” บนไทม์ไลน์ ({1} วิ{2}) ช่วงถัดไปจะต่อจากฟุตเทจนี้",
  "С какого места файла начинается клип (секунды)": "คลิปเริ่มที่ตำแหน่งใดในไฟล์ (วินาที)",
  "Кадры и звук файла без изменений (VAE). Следующие отрезки продолжают их": "เฟรมและเสียงของไฟล์ไม่เปลี่ยน (VAE) ช่วงถัดไปจะต่อจากนี้",
