  "В пресете сохраняются: системный промпт, провайдер, модель/файл, сэмплирование и контекст.": "พรีเซ็ตเก็บ: พรอมต์ระบบ ผู้ให้บริการ โมเดล/ไฟล์ การสุ่มตัวอย่าง และบริบท",
