  "Добавить промпты соседних отрезков для связности сцены": "เพิ่มพรอมต์ของคลิปข้างเคียงเพื่อความต่อเนื่องของฉาก",
  "LLM видит текущий промпт отрезка, список референсов <Picture N> и карточки персонажей": "LLM เห็นพรอมต์ของคลิปปัจจุบัน รายการอ้างอิง <Picture N> และการ์ดตัวละคร",
  "Клик — применить пресет": "คลิกเพื่อใช้พรีเซ็ต",
