  "Сервер запущен без ассистента (старая версия H3ZeroStudio). Перезапустите ComfyUI — тогда заработают выбор модели, файлы и API. Введённые настройки сохраняются в проекте и не потеряются.": "เซิร์ฟเวอร์ทำงานโดยไม่มีผู้ช่วย (H3ZeroStudio เวอร์ชันเก่า) รีสตาร์ท ComfyUI — แล้วการเลือกโมเดล ไฟล์ และ API จะใช้งานได้ การตั้งค่าที่คุณกรอกจะถูกบันทึกในโปรเจกต์และไม่สูญหาย",
