  "Встроено в ComfyUI (comfy_kitchen INT8). По умолчанию, если ядро есть на этой GPU. Тот же бэкенд, что нода «Model Attention Backend» / флаг --use-ck-attention.": "มีในตัว ComfyUI (comfy_kitchen INT8) เปิดโดยค่าเริ่มต้นเมื่อ GPU นี้รองรับเคอร์เนล ใช้แบ็กเอนด์เดียวกับโหนด “Model Attention Backend” / แฟล็ก --use-ck-attention",
  "Пакет sageattention. Недоступно — установите sageattention и перезапустите ComfyUI.": "แพ็กเกจ sageattention ใช้งานไม่ได้ — ติดตั้ง sageattention แล้วรีสตาร์ท ComfyUI",
