  "Не установлено: поставьте ComfyUI-MiniMaxH3-TeaCache (или совместимый) в custom_nodes.": "ไม่ได้ติดตั้ง: ใส่ ComfyUI-MiniMaxH3-TeaCache (หรือที่เข้ากันได้) ไว้ใน custom_nodes",
