  "comfy_api.torch_helpers недоступен в этой сборке ComfyUI.": "comfy_api.torch_helpers ใช้งานไม่ได้ในบิลด์ ComfyUI นี้",
  "Патчи навешиваются на модель H3 при загрузке (без проводов), в том числе на доработку апскейла. Бэкенды внимания взаимоисключающие.": "แพตช์จะถูกแนบกับโมเดล H3 ตอนโหลด (ไม่ต้องเชื่อมสาย) รวมถึงรีไฟน์หลังอัปสเกล แบ็กเอนด์ attention ใช้ร่วมกันไม่ได้",
