  "Окна: обученный латентный апскейлер H3 → доработка окнами (быстро, без декода/энкода)": "หน้าต่าง: latent อัปสเกลเลอร์ที่ฝึกมาของ H3 → รีไฟน์แบบหน้าต่าง (เร็ว ไม่ต้องถอด/เข้ารหัส)",
  "Плитки: апскейл → синхронные плитки (SyncTile): каждая плитка видит промпт и референсы отрезка": "ไทล์: อัปสเกล → SyncTile: แต่ละไทล์เห็นพรอมต์และอ้างอิงของคลิป",
  "растяжение латента": "ยืด latent",
  "растяжение латента (нет модели апскейлера)": "ยืด latent (ไม่มีโมเดลอัปสเกลเลอร์)",
  "Нет обученного латентного апскейлера H3 — латент просто растянут (trilinear), качество ниже. Нужна модель в models/latent_upscale_models и одна из нод: встроенная MiniMaxH3LatentUpscaleWithModel (ComfyUI ≥ PR #17412), PixaromaH3LatentUpscale (Pixaroma ≥ 1.4.238) или MinimaxH3LatentUpscaler3D (LBH).": "ไม่มี latent อัปสเกลเลอร์ที่ฝึกมาของ H3 — latent จะถูกยืดเท่านั้น (trilinear) คุณภาพต่ำกว่า ต้องมีโมเดลใน models/latent_upscale_models และหนึ่งในนี้: MiniMaxH3LatentUpscaleWithModel ในตัว (ComfyUI ≥ PR #17412), PixaromaH3LatentUpscale (Pixaroma ≥ 1.4.238) หรือ MinimaxH3LatentUpscaler3D (LBH)",
  "Финал из черновика: выбранный дубль-черновик увеличивается до финального размера обученным латентным апскейлером и дорабатывается.": "ฉบับจริงจากร่าง: เทคร่างที่เลือกจะถูกอัปสเกลเป็นขนาดฉบับจริงด้วย latent อัปสเกลเลอร์ที่ฝึกมาแล้วรีไฟน์",
  "Футаж «как есть»: его кадры кодируются VAE и проходят тот же апскейл + доработку (σ {0}) — мелкие детали восстанавливаются.": "ฟุตเทจ “ตามเดิม”: เฟรมจะถูกเข้ารหัสด้วย VAE และผ่านอัปสเกล + รีไฟน์เดียวกัน (σ {0}) — รายละเอียดเล็กๆ จะถูกฟื้นคืน",
  "Прогресс восстановлен после перезагрузки": "กู้คืนความคืบหน้าหลังโหลดใหม่แล้ว",
  " · из галереи (последний итог; текущий ролик помечен устаревшим)": " · จากแกลเลอรี (ผลลัพธ์ล่าสุด; รีลปัจจุบันถูกทำเครื่องหมายว่าล้าสมัย)",
  " · прошлый итог проекта (таймлайн изменился)": " · ผลลัพธ์ก่อนหน้าของโปรเจกต์ (ไทม์ไลน์เปลี่ยนแล้ว)",
  "Папка на компьютере, где запущен ComfyUI (например D:\\\\Видео\\\\H3). Относительный путь — внутри ComfyUI/output.": "โฟลเดอร์บนเครื่องที่รัน ComfyUI (เช่น D:\\\\Video\\\\H3) พาธแบบสัมพัทธ์จะอยู่ใน ComfyUI/output",
  "Переведи на русский кратко, без правок смысла:\n\n": "แปลเป็นภาษาไทยแบบกระชับ โดยไม่เปลี่ยนความหมาย:\n\n",
  " · {0} Мп": " · {0} MP",
  "Время": "เวลา",
  "Не удалось скопировать": "คัดลอกไม่ได้",
  "📋 Копировать промпт": "📋 คัดลอกพรอมต์",
  "Папка на компьютере, где запущен ComfyUI (например D:\\Видео\\H3). Относительный путь — внутри ComfyUI/output.": "โฟลเดอร์บนเครื่องที่รัน ComfyUI (เช่น D:\\Video\\H3) พาธแบบสัมพัทธ์จะอยู่ใน ComfyUI/output",
  "установлено": "ติดตั้งแล้ว",
  "Финал из черновика: выбранный дубль-черновик увеличивается до финального размера обученным латентным апскейлером H3 и дорабатывается коротким проходом H3 с тем же промптом и референсами. Композиция, движение и звук черновика сохраняются.": "ฉบับจริงจากร่าง: เทคร่างที่เลือกจะถูกอัปสเกลเป็นขนาดฉบับจริงด้วย latent อัปสเกลเลอร์ที่ฝึกมาของ H3 แล้วรีไฟน์ด้วยรอบ H3 สั้นๆ โดยใช้พรอมต์และอ้างอิงเดิม คงองค์ประกอบภาพ การเคลื่อนไหว และเสียงของร่างไว้",
  "Папка на компьютере, где запущен ComfyUI (например D:\\Видео\\H3). Относительный путь — внутри ComfyUI/output": "โฟลเดอร์บนเครื่องที่รัน ComfyUI (เช่น D:\\Video\\H3) พาธแบบสัมพัทธ์จะอยู่ใน ComfyUI/output",
  "Файлы сохраняются в стандартные папки ComfyUI (folder_paths / extra_model_paths.yaml). Загрузка потоковая с докачкой (.part). Опциональные модели «Скачать все» не трогает.": "ไฟล์จะถูกบันทึกในโฟลเดอร์มาตรฐานของ ComfyUI (folder_paths / extra_model_paths.yaml) ดาวน์โหลดแบบสตรีมพร้อมดาวน์โหลดต่อได้ (.part) “ดาวน์โหลดทั้งหมด” จะข้ามโมเดลที่ไม่บังคับ",
  "Футаж «как есть»: его кадры кодируются VAE и проходят тот же апскейл + доработку (σ {0}) — мелкие детали могут слегка измениться. Звук не трогается.": "ฟุตเทจ “ตามเดิม”: เฟรมจะถูกเข้ารหัสด้วย VAE และผ่านอัปสเกล + รีไฟน์เดียวกัน (σ {0}) — รายละเอียดเล็กๆ อาจเปลี่ยนเล็กน้อย เสียงไม่ถูกแตะต้อง",
